function invalidColor() {
  throw new Error('Invalid color');
}

function parseValue(value, maximum, percentageOnly) {
  const isPercentage = value.endsWith('%');
  const text = isPercentage ? value.slice(0, -1) : value;
  if (percentageOnly && !isPercentage) {
    invalidColor();
  }
  if (!/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)$/.test(text)) {
    invalidColor();
  }

  const number = Number(text);
  const limit = isPercentage ? 100 : maximum;
  if (number < 0 || number > limit) {
    invalidColor();
  }
  return isPercentage ? (number * maximum) / 100 : number;
}

function parseHue(value) {
  const match = value.match(/^([+-]?(?:\d+(?:\.\d*)?|\.\d+))(?:deg)?$/i);
  if (!match) {
    invalidColor();
  }
  const hue = Number(match[1]) % 360;
  return hue < 0 ? hue + 360 : hue;
}

function splitComponents(body) {
  if (body.includes(',')) {
    if (body.includes('/')) {
      invalidColor();
    }
    return { parts: body.split(',').map((part) => part.trim()), slash: false };
  }

  const sections = body.trim().split(/\s*\/\s*/);
  if (sections.length > 2) {
    invalidColor();
  }
  const parts = sections[0].trim().split(/\s+/);
  if (sections.length === 2) {
    parts.push(sections[1].trim());
  }
  return { parts, slash: sections.length === 2 };
}

function parseHex(input) {
  const match = input.match(/^#([0-9a-f]{3}|[0-9a-f]{4}|[0-9a-f]{6}|[0-9a-f]{8})$/i);
  if (!match) {
    return null;
  }

  let hex = match[1];
  if (hex.length <= 4) {
    hex = Array.from(hex, (digit) => digit + digit).join('');
  }
  const hasAlpha = hex.length === 8;

  return {
    red: parseInt(hex.slice(0, 2), 16),
    green: parseInt(hex.slice(2, 4), 16),
    blue: parseInt(hex.slice(4, 6), 16),
    alpha: hasAlpha ? parseInt(hex.slice(6, 8), 16) / 255 : 1,
    hasAlpha
  };
}

function hslToRgb(hue, saturation, lightness) {
  const amount = saturation * Math.min(lightness, 1 - lightness);
  const channel = (offset) => {
    const position = (offset + hue / 30) % 12;
    return 255 *
      (lightness -
        amount * Math.max(-1, Math.min(position - 3, 9 - position, 1)));
  };
  return { red: channel(0), green: channel(8), blue: channel(4) };
}

function parseFunction(input) {
  const match = input.match(/^(rgb|rgba|hsl|hsla)\((.*)\)$/i);
  if (!match) {
    return null;
  }

  const name = match[1].toLowerCase();
  const split = splitComponents(match[2]);
  const hasAlpha = split.parts.length === 4;
  if (
    split.parts.some((part) => part === '') ||
    (!hasAlpha && split.parts.length !== 3) ||
    (name.endsWith('a') && !hasAlpha) ||
    (!name.endsWith('a') && hasAlpha && !split.slash)
  ) {
    invalidColor();
  }

  const alpha = hasAlpha ? parseValue(split.parts[3], 1) : 1;
  if (name.startsWith('rgb')) {
    return {
      red: parseValue(split.parts[0], 255),
      green: parseValue(split.parts[1], 255),
      blue: parseValue(split.parts[2], 255),
      alpha,
      hasAlpha
    };
  }

  const hue = parseHue(split.parts[0]);
  const saturation = parseValue(split.parts[1], 1, true);
  const lightness = parseValue(split.parts[2], 1, true);
  return { ...hslToRgb(hue, saturation, lightness), alpha, hasAlpha };
}

function rgbToHsl(red, green, blue) {
  const r = red / 255;
  const g = green / 255;
  const b = blue / 255;
  const maximum = Math.max(r, g, b);
  const minimum = Math.min(r, g, b);
  const difference = maximum - minimum;
  const lightness = (maximum + minimum) / 2;
  let hue = 0;
  let saturation = 0;

  if (difference !== 0) {
    saturation = difference / (1 - Math.abs(2 * lightness - 1));
    if (maximum === r) {
      hue = 60 * (((g - b) / difference) % 6);
    } else if (maximum === g) {
      hue = 60 * ((b - r) / difference + 2);
    } else {
      hue = 60 * ((r - g) / difference + 4);
    }
  }
  if (hue < 0) {
    hue += 360;
  }

  return { hue, saturation, lightness };
}

function formatNumber(value, digits) {
  return String(Number(value.toFixed(digits)));
}

function hexByte(value) {
  return Math.round(value).toString(16).padStart(2, '0').toUpperCase();
}

function formatRgb(color) {
  const channels = [color.red, color.green, color.blue].map(Math.round).join(', ');
  return color.hasAlpha
    ? 'rgba(' + channels + ', ' + formatNumber(color.alpha, 3) + ')'
    : 'rgb(' + channels + ')';
}

function formatHsl(color) {
  const hsl = rgbToHsl(color.red, color.green, color.blue);
  const values =
    formatNumber(hsl.hue, 2) +
    ', ' +
    formatNumber(hsl.saturation * 100, 2) +
    '%, ' +
    formatNumber(hsl.lightness * 100, 2) +
    '%';
  return color.hasAlpha
    ? 'hsla(' + values + ', ' + formatNumber(color.alpha, 3) + ')'
    : 'hsl(' + values + ')';
}

function formatHex(color) {
  const channels = [color.red, color.green, color.blue];
  if (color.hasAlpha) {
    channels.push(color.alpha * 255);
  }
  return '#' + channels.map(hexByte).join('');
}

function process(data) {
  const input = data.selection.trim();
  const hex = parseHex(input);
  if (hex) {
    return formatRgb(hex);
  }

  const color = parseFunction(input);
  if (!color) {
    invalidColor();
  }
  return /^rgba?\(/i.test(input) ? formatHsl(color) : formatHex(color);
}
